import{_ as e,o as a,c as o,ag as s,j as n}from"./chunks/framework.KxDd3USm.js";const x=JSON.parse('{"title":"05.2 进程调度与 PV 操作 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"05-操作系统/02-进程调度与PV操作.md","filePath":"05-操作系统/02-进程调度与PV操作.md"}'),r={name:"05-操作系统/02-进程调度与PV操作.md"},l={class:"fig"},p={"data-figure-id":"figure-17",viewBox:"0 0 720 300",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"前趋图 A 到 B 和 C，B 和 C 到 D。每条弧对应一个初值为零的信号量：A 在末尾 V S1、V S2；B 开头 P S1、末尾 V S3；C 开头 P S2、末尾 V S4；D 开头 P S3、P S4。因此 D 必须等待 B 和 C 都完成。"};function i(d,t,u,c,g,h){return a(),o("div",null,[t[2]||(t[2]=s(`<h1 id="_05-2-进程调度与-pv-操作-★★★" tabindex="-1">05.2 进程调度与 PV 操作 ★★★ <a class="header-anchor" href="#_05-2-进程调度与-pv-操作-★★★" aria-label="Permalink to &quot;05.2 进程调度与 PV 操作 ★★★&quot;">​</a></h1><h3 id="为什么要算周转时间" tabindex="-1">为什么要算周转时间 <a class="header-anchor" href="#为什么要算周转时间" aria-label="Permalink to &quot;为什么要算周转时间&quot;">​</a></h3><p>用户交一个作业给系统，最关心的就是&quot;多久能跑完&quot;。周转时间衡量这个：从<strong>到达</strong>到<strong>完成</strong>的全部等待 + 运行时间。调度算法不同，周转时间不同——考题就是给几个作业的到达/运行时间，让你按某算法排顺序再求平均周转时间。</p><h3 id="公式三件套" tabindex="-1">公式三件套 <a class="header-anchor" href="#公式三件套" aria-label="Permalink to &quot;公式三件套&quot;">​</a></h3><ul><li><strong>通用形式</strong>：周转时间 = 完成时刻 − 到达时刻；平均周转时间 = 各作业周转时间之和 ÷ 作业数；带权周转时间 = 周转时间 ÷ 实际运行时间。</li><li><strong>代入算例</strong>：作业 J1 时刻 0 到达、需运行 4；J2 时刻 1 到达、需运行 3；J3 时刻 2 到达、需运行 1。按先来先服务（FCFS）单道顺序执行：J1 在 0–4 完成，周转 = 4−0 = 4；J2 在 4–7 完成，周转 = 7−1 = 6；J3 在 7–8 完成，周转 = 8−2 = 6。平均周转时间 = (4+6+6)/3 = 16/3 ≈ 5.33。</li><li><strong>手算口诀</strong>：先列表填&quot;开始时刻、完成时刻&quot;两列（完成 = 上一个完成时刻与本作业到达时刻中较大者 + 运行时间），再用&quot;完成减到达&quot;一列竖式扫下去。</li></ul><h3 id="常考调度算法" tabindex="-1">常考调度算法 <a class="header-anchor" href="#常考调度算法" aria-label="Permalink to &quot;常考调度算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>规则</th><th>特征词</th></tr></thead><tbody><tr><td>FCFS 先来先服务</td><td>按到达顺序</td><td>&quot;先来先服务&quot;</td></tr><tr><td>SJF 短作业优先（非抢占）</td><td>可运行作业中挑<strong>运行时间最短</strong>的</td><td>&quot;短作业优先&quot;&quot;平均周转时间最短&quot;</td></tr></tbody></table><p><strong>反例演示（易错）</strong>：SJF 非抢占时，<strong>时刻 0 只能从已到达的作业里挑短的</strong>，不是全场谁短谁先。上例改按 SJF：t=0 只有 J1 已到 → 仍先跑 J1（0–4）；t=4 时 J2(需 3)、J3(需 1) 都在等 → 挑短的 J3（4–5，周转 5−2 = 3）；再跑 J2（5–8，周转 8−1 = 7）。平均 = (4+3+7)/3 = 14/3 ≈ 4.67 &lt; 5.33 ✓（SJF 平均周转更短，这正是它的卖点）。若错把 J3 提到最前面先跑，就掉进&quot;未到达就运行&quot;的陷阱。</p><p><strong>应试动作</strong>：背公式&quot;周转 = 完成 − 到达&quot;；SJF 题每一步都先检查&quot;该时刻这个作业到了没有&quot;；选项给分数（16/3、14/3）时别慌，保留分数或算到两位小数即可。</p><h2 id="第四节-进程同步与互斥-pv-操作-★★★-必考" tabindex="-1">第四节 进程同步与互斥：PV 操作 ★★★（必考） <a class="header-anchor" href="#第四节-进程同步与互斥-pv-操作-★★★-必考" aria-label="Permalink to &quot;第四节 进程同步与互斥：PV 操作 ★★★（必考）&quot;">​</a></h2><h3 id="为什么要互斥-临界资源" tabindex="-1">为什么要互斥：临界资源 <a class="header-anchor" href="#为什么要互斥-临界资源" aria-label="Permalink to &quot;为什么要互斥：临界资源&quot;">​</a></h3><p>两个进程同时往同一台打印机上输出，纸上的内容就会交错成一团乱码。像打印机这种<strong>同一时刻只允许一个进程使用的资源</strong>叫<strong>临界资源</strong>，进程中访问临界资源的那段代码叫<strong>临界区</strong>。注意区分：临界资源必须互斥使用；普通共享资源（如可重入的代码）允许多进程同时用。</p><p>临界区管理的四条准则（选择题考过名称与含义）：<strong>有空即进、无空则等、有限等待、让权等待</strong>（进不了临界区就释放 CPU，避免&quot;忙等&quot;）。</p><h3 id="信号量与-pv-一个会-记账-的变量" tabindex="-1">信号量与 PV：一个会&quot;记账&quot;的变量 <a class="header-anchor" href="#信号量与-pv-一个会-记账-的变量" aria-label="Permalink to &quot;信号量与 PV：一个会&quot;记账&quot;的变量&quot;">​</a></h3><p><strong>信号量 S 是一个特殊变量</strong>，本质是资源账本：S &gt; 0 表示还剩 S 个资源可用；S = 0 表示资源刚好用光、无人排队；<strong>S &lt; 0 的绝对值 = 排队等资源的进程数</strong>。</p><ul><li><strong>P(S)</strong>（申请）：S 减 1；若 S &lt; 0，本进程阻塞进等待队列。</li><li><strong>V(S)</strong>（释放）：S 加 1；若 S ≤ 0（说明有人在排队），唤醒一个等待进程。</li></ul><p>初学者最容易问：&quot;不就是个加减法吗，为什么要绑定阻塞/唤醒？&quot;——因为判断和等待必须<strong>一步完成</strong>：如果&quot;先查 S 再决定等不等&quot;分成两步，两个进程可能同时查到&quot;还有 1 个&quot;然后都进去，互斥就破了。PV 把&quot;查账 + 排队/叫号&quot;做成了不可拆的整体。</p><p><strong>初值怎么定（核心结论）</strong>：</p><table tabindex="0"><thead><tr><th>模型</th><th>信号量含义</th><th>初值</th></tr></thead><tbody><tr><td><strong>互斥</strong>（多进程抢同一资源）</td><td>资源数量</td><td>= 资源数（1 台打印机 → 1；3 台同类打印机 → 3）</td></tr><tr><td><strong>同步</strong>（前者做完了后者才能做）</td><td>&quot;前者已完成&quot;这个消息</td><td>一般为 <strong>0</strong></td></tr><tr><td><strong>前趋图</strong></td><td>每条有向弧一个信号量</td><td>全为 <strong>0</strong></td></tr></tbody></table><p><strong>信号量取值范围题（公式三件套）</strong>：</p><ul><li>通用形式：n 个进程共享 k 个同类资源，S 初值 k，则 S 的最大值 = k，最小值 = k − n（负到&quot;全部进程都在排队&quot;为止）。</li><li>代入算例：10 个进程共享 3 台打印机：最大 3，最小 3 − 10 = −7，即 S ∈ [−7, 3]。</li><li>手算口诀：<strong>&quot;上界是初值，下界是初值减进程数&quot;</strong>。</li></ul><h3 id="前趋图配-pv-套路题-★★★" tabindex="-1">前趋图配 PV：套路题（★★★） <a class="header-anchor" href="#前趋图配-pv-套路题-★★★" aria-label="Permalink to &quot;前趋图配 PV：套路题（★★★）&quot;">​</a></h3><p>前趋图刻画&quot;哪些任务必须等哪些任务做完才能开始&quot;（思想与数据结构的拓扑排序一致，见 <a href="/ruankao/01-数据结构与算法/03-图.html">第 01 课「图」</a> 第 3.5 节；与软件工程的关键路径网络图也同源）。</p><p><strong>规则（背死）</strong>：</p><ol><li><strong>图中有几条有向弧，就定义几个信号量</strong>（每条弧一个，初值全为 0）；</li><li>每条弧的<strong>起点</strong>（前趋任务）末尾做 <strong>V</strong>（&quot;我做完了&quot;），<strong>终点</strong>（后继任务）开头做 <strong>P</strong>（&quot;等我的前置完成&quot;）；</li><li>一个任务有几条入弧，开头就要连续做几个 P；有几条出弧，末尾就连续做几个 V。</li></ol><p><strong>代入算例</strong>：弧为 A→B、A→C、B→D、C→D 共 4 条 → 信号量 S1～S4，初值均为 0：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A: 执行; V(S1); V(S2);</span></span>
<span class="line"><span>B: P(S1); 执行; V(S3);</span></span>
<span class="line"><span>C: P(S2); 执行; V(S4);</span></span>
<span class="line"><span>D: P(S3); P(S4); 执行;</span></span></code></pre></div>`,27)),n("figure",l,[(a(),o("svg",p,[...t[0]||(t[0]=[s('<defs><marker id="pv-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><circle cx="110" cy="150" r="32" class="n"></circle><text x="104" y="156" class="t">A</text><circle cx="340" cy="80" r="32" class="n"></circle><text x="334" y="86" class="t">B</text><circle cx="340" cy="220" r="32" class="n"></circle><text x="334" y="226" class="t">C</text><circle cx="585" cy="150" r="32" class="n"></circle><text x="579" y="156" class="t">D</text><path d="M140 137L309 91" class="e" marker-end="url(#pv-arrow)"></path><text x="202" y="100" class="s">S1（初值 0）</text><path d="M140 163L309 209" class="e" marker-end="url(#pv-arrow)"></path><text x="202" y="205" class="s">S2（初值 0）</text><path d="M371 89L554 137" class="e" marker-end="url(#pv-arrow)"></path><text x="444" y="104" class="s">S3（初值 0）</text><path d="M371 211L554 163" class="e" marker-end="url(#pv-arrow)"></path><text x="444" y="205" class="s">S4（初值 0）</text><text x="70" y="201" class="v">末尾：V(S1)、V(S2)</text><text x="276" y="35" class="p">开头：P(S1)</text><text x="310" y="132" class="v">末尾：V(S3)</text><text x="276" y="278" class="p">开头：P(S2)</text><text x="310" y="174" class="v">末尾：V(S4)</text><text x="535" y="110" class="p">开头：P(S3)、P(S4)</text>',23)])])),t[1]||(t[1]=n("figcaption",null,"逐弧核对：起点任务末尾 V，终点任务开头 P；四条弧正好对应四个信号量。",-1))]),t[3]||(t[3]=s(`<p><strong>反例演示（易错）</strong>：把 V 写在弧的终点、P 写在起点——顺序反了：变成&quot;后继先 V 报信、前趋再 P 等待&quot;，而信号量初值是 0，前趋 P 时会永远阻塞，整张图谁都跑不起来。记住口诀：<strong>&quot;V 在前驱末，P 在后继初&quot;</strong>。另一易错点：同步信号量与互斥信号量混用初值——同步（前趋图）初值 0，互斥初值 = 资源数，二者不能抄混。</p><h3 id="生产者-消费者-互斥-同步组合题" tabindex="-1">生产者-消费者：互斥 + 同步组合题 <a class="header-anchor" href="#生产者-消费者-互斥-同步组合题" aria-label="Permalink to &quot;生产者-消费者：互斥 + 同步组合题&quot;">​</a></h3><p><strong>动机</strong>：一个进程往缓冲区放数据（生产者），一个进程从缓冲区取（消费者）。缓冲区格子是<strong>临界资源</strong>（同一时刻只容一个放/取），同时还有两条先后关系：缓冲区<strong>满</strong>时生产者要等消费者取走，缓冲区<strong>空</strong>时消费者要等生产者放入。因此至少三类信号量：</p><ul><li>互斥 <code>mutex</code>，初值 1，保护&quot;进出缓冲区（放/取）&quot;这段临界区；</li><li>同步 <code>empty</code>，初值 = 缓冲区格数（还剩几个空位）；</li><li>同步 <code>full</code>，初值 0（已放入几格数据）。</li></ul><p><strong>同步为什么&quot;先 P 后 V&quot;（核心，必背）</strong>：同步信号量记的是&quot;资源余量&quot;，<strong>用前先 P（检查、不够就等），用后 V（归还）</strong>——这与互斥只在初值上不同。而且<strong>同步的 P 必须放在互斥的 P 之前</strong>：若反了，缓冲区满时生产者占着 <code>mutex</code> 去等 <code>empty</code>，消费者却要 <code>mutex</code> 才能取出、腾出空位 → 互相等 = 死锁。</p><p><strong>代入算例</strong>：缓冲区可放 5 格，初态全空。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>semaphore mutex=1, empty=5, full=0;</span></span>
<span class="line"><span>生产者：P(empty);   // 先申请空位，满则等</span></span>
<span class="line"><span>        P(mutex);   // 再进临界区</span></span>
<span class="line"><span>        放入数据;</span></span>
<span class="line"><span>        V(mutex);</span></span>
<span class="line"><span>        V(full);    // 通知多了一格数据</span></span>
<span class="line"><span>消费者：P(full);    // 有数据才取，空则等</span></span>
<span class="line"><span>        P(mutex);</span></span>
<span class="line"><span>        取出数据;</span></span>
<span class="line"><span>        V(mutex);</span></span>
<span class="line"><span>        V(empty);   // 归还一个空位</span></span></code></pre></div><p><strong>口诀：&quot;同步 P 在前、互斥 P 在后，V 成对跟各自操作后&quot;</strong>。</p><p><strong>反例演示（易错）</strong>：① 把 <code>P(mutex)</code> 提到 <code>P(empty)</code> 之前（见上&quot;为什么&quot;），缓冲区满即死锁；② <code>empty</code> 初值误设 0（空位应是缓冲区容量 5，不是 0）；③ 生产者也写 <code>P(full)</code>/<code>V(empty)</code>（把消费者的同步抄反，会在空缓冲时误等）。</p><p><strong>应试动作</strong>：① 互斥 → 初值 = 资源数；同步/前趋 → 初值 0；② 取值范围 = [初值−进程数， 初值]；③ 前趋图按&quot;弧数 = 信号量数、V 起点末、P 终点初&quot;机械填写，填完逐弧检查一遍&quot;每条弧恰好一个 V 和一个 P&quot;。这种题若以小问嵌在案例大题里（历史上考过整道大题），按同一套路做。并发互斥的思想与数据库的锁机制同源，可对照 <a href="/ruankao/02-数据库系统/06-事务并发与故障恢复.html">02-数据库系统.md</a> 的并发控制一节。</p>`,10))])}const P=e(r,[["render",i]]);export{x as __pageData,P as default};
